// Expo config plugin for distributable Android release builds.
//
// The android/ project is generated by `expo prebuild`, so changes to it have to
// be applied here rather than by hand. This plugin:
//
// 1. Signs release builds with our own upload key when it is provided as Gradle
//    properties (see README "Releases"):
//      CADENCE_UPLOAD_STORE_FILE, CADENCE_UPLOAD_STORE_PASSWORD,
//      CADENCE_UPLOAD_KEY_ALIAS,  CADENCE_UPLOAD_KEY_PASSWORD
//    Pass them with -P..., ORG_GRADLE_PROJECT_<name> env vars, or
//    ~/.gradle/gradle.properties. Without them, release builds fall back to the
//    public debug key: fine for local testing, never for distribution.
//
// 2. Derives android.versionCode from the "version" field (1.2.3 -> 10203) unless
//    it is set explicitly, so every new version installs as an upgrade.

const { withAppBuildGradle } = require("expo/config-plugins");

const MARKER = "CADENCE_UPLOAD_STORE_FILE";

function versionCodeFrom(version) {
    const match = /^(\d+)\.(\d+)\.(\d+)$/.exec(version ?? "");
    if (!match) {
        throw new Error(`withAndroidRelease: "version" must be MAJOR.MINOR.PATCH, got "${version}"`);
    }
    const [major, minor, patch] = match.slice(1).map(Number);
    if (minor > 99 || patch > 99) {
        throw new Error(`withAndroidRelease: minor and patch must be <= 99, got "${version}"`);
    }
    return major * 10000 + minor * 100 + patch;
}

function addReleaseSigning(gradle) {
    if (gradle.includes(MARKER)) return gradle;

    const releaseSigningConfig = `
        release {
            if (findProperty('CADENCE_UPLOAD_STORE_FILE')) {
                storeFile file(findProperty('CADENCE_UPLOAD_STORE_FILE'))
                storePassword findProperty('CADENCE_UPLOAD_STORE_PASSWORD')
                keyAlias findProperty('CADENCE_UPLOAD_KEY_ALIAS')
                keyPassword findProperty('CADENCE_UPLOAD_KEY_PASSWORD')
            }
        }`;

    const withConfig = gradle.replace(/signingConfigs\s*\{/, (m) => m + releaseSigningConfig);

    // Only the signingConfig inside buildTypes { release { ... } }.
    const withBuildType = withConfig.replace(
        /(buildTypes\s*\{[\s\S]*?\brelease\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/,
        "$1signingConfig findProperty('CADENCE_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug",
    );

    if (withConfig === gradle || withBuildType === withConfig) {
        // The Expo template changed shape; fail loudly instead of shipping debug-signed APKs.
        throw new Error("withAndroidRelease: couldn't find signingConfigs/buildTypes.release in app/build.gradle");
    }
    return withBuildType;
}

module.exports = function withAndroidRelease(config) {
    config.android = config.android ?? {};
    config.android.versionCode = config.android.versionCode ?? versionCodeFrom(config.version);

    return withAppBuildGradle(config, (cfg) => {
        if (cfg.modResults.language !== "groovy") {
            throw new Error("withAndroidRelease: expected a Groovy app/build.gradle");
        }
        cfg.modResults.contents = addReleaseSigning(cfg.modResults.contents);
        return cfg;
    });
};
